import React, { useState } from 'react';
import api from '../api';

function AddTrip({ setTrip }) {
    const [tripName, setTripName] = useState('');
    const [familyHeads, setFamilyHeads] = useState(['']); // Start with one empty family head
    const [error, setError] = useState('');
    const [isLoading, setIsLoading] = useState(false);

    const handleAddTrip = async (e) => {
        e.preventDefault();
        setError('');
        setIsLoading(true);

        try {
            if (!tripName || familyHeads.some(head => !head.trim())) {
                setError('Please fill in all fields');
                setIsLoading(false);
                return;
            }

            const tripData = {
                name: tripName,
                families: familyHeads.filter(head => head.trim()).map(head => ({
                    head: head.trim(),
                    members: []
                }))
            };

            console.log('Sending trip data:', tripData);

            const response = await api.post('/trips', tripData);

            if (response?.data) {
                console.log('Trip created:', response.data);
                setTrip(response.data);
            } else {
                throw new Error('No response data received');
            }
        } catch (error) {
            console.error('Error creating trip:', error);
            setError(error.response?.data?.message || 'Failed to create trip. Please try again.');
        } finally {
            setIsLoading(false);
        }
    };

    const handleAddFamilyHead = () => {
        setFamilyHeads([...familyHeads, '']);
    };

    const handleRemoveFamilyHead = (index) => {
        if (familyHeads.length > 1) {
            const updated = familyHeads.filter((_, i) => i !== index);
            setFamilyHeads(updated);
        }
    };

    const handleFamilyHeadChange = (index, value) => {
        const updated = [...familyHeads];
        updated[index] = value;
        setFamilyHeads(updated);
    };

    return (
        <div style={{ maxWidth: '500px', margin: '0 auto', padding: '20px' }}>
            <form onSubmit={handleAddTrip}>
                <h2>Add New Trip</h2>

                {error && <div style={{ color: 'red', marginBottom: '10px' }}>{error}</div>}

                <div style={{ marginBottom: '15px' }}>
                    <label>Trip Name:</label>
                    <input
                        type="text"
                        value={tripName}
                        onChange={(e) => setTripName(e.target.value)}
                        style={{ width: '100%', padding: '8px', marginTop: '5px' }}
                        required
                    />
                </div>

                <div style={{ marginBottom: '15px' }}>
                    <label>Family Heads:</label>
                    {familyHeads.map((head, index) => (
                        <div key={index} style={{ 
                            display: 'flex', 
                            gap: '10px', 
                            marginBottom: '10px',
                            alignItems: 'center'
                        }}>
                            <input
                                type="text"
                                value={head}
                                onChange={(e) => handleFamilyHeadChange(index, e.target.value)}
                                placeholder={`Family Head ${index + 1}`}
                                style={{ flex: 1, padding: '8px' }}
                                required
                            />
                            {familyHeads.length > 1 && (
                                <button
                                    type="button"
                                    onClick={() => handleRemoveFamilyHead(index)}
                                    style={{
                                        padding: '8px',
                                        backgroundColor: '#dc3545',
                                        color: 'white',
                                        border: 'none',
                                        borderRadius: '4px',
                                        cursor: 'pointer'
                                    }}
                                >
                                    Remove
                                </button>
                            )}
                        </div>
                    ))}
                    <button
                        type="button"
                        onClick={handleAddFamilyHead}
                        style={{
                            width: '100%',
                            padding: '8px',
                            backgroundColor: '#28a745',
                            color: 'white',
                            border: 'none',
                            borderRadius: '4px',
                            marginTop: '10px',
                            cursor: 'pointer'
                        }}
                    >
                        Add Another Family Head
                    </button>
                </div>

                <button
                    type="submit"
                    style={{
                        width: '100%',
                        padding: '10px',
                        backgroundColor: '#007bff',
                        color: 'white',
                        border: 'none',
                        borderRadius: '4px',
                        cursor: 'pointer',
                        marginTop: '20px'
                    }}
                    disabled={isLoading}
                >
                    {isLoading ? 'Creating Trip...' : 'Create Trip'}
                </button>
            </form>
        </div>
    );
}

export default AddTrip;
